// Saudi Arabia's 13 administrative regions, simplified from Natural Earth admin-1 boundaries
// (1:10m, public domain) and projected equirectangularly at the Kingdom's mid-latitude into a
// box 1000 units wide. Generated offline from the source data; do not edit the paths by hand.
export const SAUDI_MAP_SIZE = Object.freeze({ width: 1000, height: 820 })

const PROJECTION = Object.freeze({ lon0: 34.5728, lat1: 32.1213, cos: 0.91179, scale: 52.0653 })

// A city's decimal-degree coordinates placed in the same box as the region paths.
export function projectPoint(latitude, longitude) {
  return {
    x: (longitude - PROJECTION.lon0) * PROJECTION.cos * PROJECTION.scale,
    y: (PROJECTION.lat1 - latitude) * PROJECTION.scale,
  }
}

